package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Node_absUrl_TriageGen1Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Test
    public void testAbsUrl_NullAttributeKey() {
        Node node = new Element(""); // Using Element as a concrete implementation of Node
        thrown.expect(IllegalArgumentException.class);
        node.absUrl(null);
    }

    @Test
    public void testAbsUrl_EmptyAttributeKey() {
        Node node = new Element("");
        thrown.expect(IllegalArgumentException.class);
        node.absUrl("");
    }

    @Test
    public void testAbsUrl_NoAttributePresent() {
        Node node = new Element("http://example.com/");
        // attribute "href" does not exist
        assertEquals("", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_ValidRelativeUrlWithBase() {
        Node node = new Element("http://example.com/path/page.html");
        node.attr("href", "sub/page.html");
        // Expected: http://example.com/path/sub/page.html
        assertEquals("http://example.com/path/sub/page.html", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_ValidAbsoluteUrlInAttribute() {
        Node node = new Element("http://example.com/");
        node.attr("href", "https://other.com/image.png");
        assertEquals("https://other.com/image.png", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_MalformedBaseUriButAttributeIsAbsolute() {
        // baseUri is malformed
        Node node = new Element("not-a-url");
        node.attr("href", "http://absolute.com/test");
        // The catch block for base = new URL(baseUri) should trigger, 
        // then try to parse the attribute as an absolute URL.
        assertEquals("http://absolute.com/test", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_MalformedBaseUriAndAttributeIsRelative() {
        // baseUri is malformed
        Node node = new Element("not-a-url");
        node.attr("href", "relative/path");
        // The catch block for base = new URL(baseUri) triggers.
        // Then tries new URL("relative/path") which throws MalformedURLException.
        // The outer catch returns "".
        assertEquals("", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_MalformedAttributeUrlWithValidBase() {
        Node node = new Element("http://example.com/");
        node.attr("href", " ://invalid-url");
        // base is valid, but new URL(base, relUrl) throws MalformedURLException
        assertEquals("", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_WorkaroundCase() {
        // Testing the comment: //path/file + ?foo
        // This ensures the URL resolution logic behaves as expected by the code
        Node node = new Element("http://example.com/");
        node.attr("href", "//path/file?foo");
        // java.net.URL(base, relUrl) handles // as protocol-relative
        assertEquals("http://path/file?foo", node.absUrl("href"));
    }

    // Concrete implementation for testing purposes since Node is abstract
    private static class Element extends Node {
        private final String baseUri;
        private final Attributes attributes;

        Element(String baseUri) {
            super(baseUri);
            this.baseUri = baseUri;
            this.attributes = new Attributes();
        }

        Element(String baseUri, Attributes attributes) {
            super(baseUri, attributes);
            this.baseUri = baseUri;
            this.attributes = attributes;
        }

        @Override
        public String nodeName() {
            return "element";
        }

        @Override
        public String attr(String attributeKey) {
            return attributes.get(attributeKey);
        }

        @Override
        public Attributes attributes() {
            return attributes;
        }

        @Override
        public boolean hasAttr(String attributeKey) {
            return attributes.containsKey(attributeKey);
        }

        @Override
        public Node attr(String attributeKey, String attributeValue) {
            attributes.put(attributeKey, attributeValue);
            return this;
        }

        @Override
        public Node removeAttr(String attributeKey) {
            attributes.remove(attributeKey);
            return this;
        }
    }
}
